import React, { useState } from 'react';
import { apiDangNhap } from '../api/goi_api'; // Đảm bảo bạn đã tạo file này trong folder api

const DangNhap = () => {
    const [form, setForm] = useState({ ten: '', mk: '' });

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            const res = await apiDangNhap({
                ten_dang_nhap: form.ten,
                mat_khau: form.mk
            });
            alert("Đăng nhập thành công! Chào " + res.data.user.ten_dang_nhap);
            // Chuyển hướng nếu cần: window.location.href = '/quan-ly';
        } catch (error) {
            alert(error.response?.data?.message || "Lỗi kết nối server");
        }
    };

    return (
        <div style={styles.container}>
            <div style={styles.loginBox}>
                {/* Cột trái: Màu tối giống ảnh mẫu */}
                <div style={styles.leftSide}>
                    <div style={styles.brand}>
                        <div style={styles.logoCircle}>🛡️</div>
                        <h1 style={styles.brandName}>A&RMS</h1>
                    </div>
                    <div style={styles.welcomeText}>
                        <p style={{ margin: 0, fontWeight: 'bold' }}>Chào mừng đã đến với A&RMS,</p>
                        <span style={{ fontSize: '14px', opacity: 0.8 }}>Phần mềm quản lý căn hộ và khu dân cư!</span>
                    </div>
                </div>

                {/* Cột phải: Form nhập liệu */}
                <div style={styles.rightSide}>
                    <h2 style={styles.title}>Apartment & Resident Management System</h2>
                    <form onSubmit={handleLogin} style={styles.form}>
                        <div style={styles.inputWrapper}>
                            <input 
                                type="text" 
                                placeholder="Tài khoản ..." 
                                style={styles.input}
                                onChange={(e) => setForm({...form, ten: e.target.value})}
                                required
                            />
                        </div>
                        <div style={styles.inputWrapper}>
                            <input 
                                type="password" 
                                placeholder="Mật khẩu ..." 
                                style={styles.input}
                                onChange={(e) => setForm({...form, mk: e.target.value})}
                                required
                            />
                        </div>
                        <button type="submit" style={styles.loginBtn}>Đăng nhập</button>
                    </form>
                    <p style={styles.registerLink}>Đăng ký tài khoản mới</p>
                </div>
            </div>
        </div>
    );
};

// Toàn bộ CSS để giao diện giống 99% ảnh mẫu
const styles = {
    container: {
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: '#f0f2f5',
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
    },
    loginBox: {
        display: 'flex',
        width: '850px',
        height: '450px',
        backgroundColor: '#fff',
        borderRadius: '12px',
        boxShadow: '0 15px 35px rgba(0,0,0,0.2)',
        overflow: 'hidden'
    },
    leftSide: {
        flex: 1,
        backgroundColor: '#1a1a1a', // Màu tối
        color: '#fff',
        padding: '40px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        backgroundImage: 'linear-gradient(45deg, #1a1a1a 0%, #333 100%)'
    },
    brand: {
        display: 'flex',
        alignItems: 'center',
        marginBottom: '30px'
    },
    logoCircle: {
        fontSize: '30px',
        marginRight: '15px'
    },
    brandName: {
        fontSize: '28px',
        margin: 0,
        letterSpacing: '2px'
    },
    welcomeText: {
        lineHeight: '1.6'
    },
    rightSide: {
        flex: 1.5,
        padding: '50px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        textAlign: 'center'
    },
    title: {
        fontSize: '20px',
        color: '#555',
        marginBottom: '30px',
        fontWeight: '500'
    },
    form: {
        display: 'flex',
        flexDirection: 'column',
        gap: '15px'
    },
    input: {
        width: '100%',
        padding: '12px 15px',
        border: '1px solid #ddd',
        borderRadius: '6px',
        fontSize: '15px',
        outline: 'none',
        boxSizing: 'border-box'
    },
    loginBtn: {
        padding: '12px',
        backgroundColor: '#5c3d2e', // Màu nâu gỗ giống mẫu
        color: '#fff',
        border: 'none',
        borderRadius: '6px',
        fontSize: '16px',
        fontWeight: 'bold',
        cursor: 'pointer',
        transition: 'background 0.3s'
    },
    registerLink: {
        marginTop: '20px',
        color: '#28a745',
        cursor: 'pointer',
        fontSize: '14px',
        textDecoration: 'none'
    }
};

export default DangNhap;
